"use client";

import { useEffect, useState } from "react";
import { getAnomalies } from "@/lib/api/patterns";
import { AnomalyList } from "@/components/anomaly";
import { AlertTriangle } from "lucide-react";

/* ================= TYPES MATCH BACKEND ================= */

interface Anomaly {
  id: string;
  identityId: string;
  cameraId: string;
  anomalyType: string;
  timestamp: string;
}

/* ======================================================= */

export default function AnomaliesPage() {
  const [anomalies, setAnomalies] = useState<Anomaly[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchAnomalies = async () => {
      setIsLoading(true);

      try {
        const data = await getAnomalies();
        setAnomalies(data);
      } catch (error) {
        console.error("Error fetching anomalies:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchAnomalies();
  }, []);

  /* ===== BASIC STATS ===== */

  const anomalyCounts = {
    total: anomalies.length,
    loitering: anomalies.filter((a) =>
      a.anomalyType?.toLowerCase().includes("loiter"),
    ).length,
    unusual: anomalies.filter((a) =>
      a.anomalyType?.toLowerCase().includes("unusual"),
    ).length,
    other: anomalies.filter(
      (a) =>
        !a.anomalyType?.toLowerCase().includes("loiter") &&
        !a.anomalyType?.toLowerCase().includes("unusual"),
    ).length,
  };

  return (
    <div className="space-y-6 p-6">
      {/* ================= PAGE HEADER ================= */}

      <div>
        <h1 className="text-3xl font-bold text-white mb-2">Anomalies</h1>
        <p className="text-gray-400">
          Monitor and investigate detected anomalous behaviour
        </p>
      </div>

      {/* ================= METRICS ================= */}

      <div className="grid grid-cols-4 gap-4">
        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Total Anomalies</p>
          <p className="text-2xl font-bold text-white mt-1">
            {anomalyCounts.total}
          </p>
        </div>

        <div className="bg-[#222] border border-red-500/50 rounded-lg p-4">
          <p className="text-sm text-red-400">Loitering</p>
          <p className="text-2xl font-bold text-red-400 mt-1">
            {anomalyCounts.loitering}
          </p>
        </div>

        <div className="bg-[#222] border border-yellow-500/50 rounded-lg p-4">
          <p className="text-sm text-yellow-400">Unusual Movement</p>
          <p className="text-2xl font-bold text-yellow-400 mt-1">
            {anomalyCounts.unusual}
          </p>
        </div>

        <div className="bg-[#222] border border-blue-500/50 rounded-lg p-4">
          <p className="text-sm text-blue-400">Other Alerts</p>
          <p className="text-2xl font-bold text-blue-400 mt-1">
            {anomalyCounts.other}
          </p>
        </div>
      </div>

      {/* ================= ALERT BANNER ================= */}

      {anomalyCounts.total > 0 && (
        <div className="bg-red-500/10 border border-red-500/50 rounded-lg p-4 flex items-start gap-3">
          <AlertTriangle
            className="text-red-400 flex-shrink-0 mt-0.5"
            size={20}
          />
          <div>
            <p className="font-semibold text-red-400">Anomaly Activity</p>
            <p className="text-sm text-red-300 mt-1">
              {anomalyCounts.total} anomaly events detected across the monitored
              cameras. Review the timeline below.
            </p>
          </div>
        </div>
      )}

      {/* ================= TIMELINE ================= */}

      <div>
        <h2 className="text-xl font-bold text-white mb-4">
          Anomaly Detection Timeline
        </h2>

        <AnomalyList anomalies={anomalies} isLoading={isLoading} />
      </div>
    </div>
  );
}
